// Requête NVIDIA NIM, format OpenAI. L'image passe en bloc « image_url » :
// mesuré, la balise <img> des anciens NIM n'est pas vue comme une image ici —
// le modèle décrit alors le base64 comme du texte, en 40 s.
//
// Pas de « response_format » : le décodage guidé de ce point d'accès tombe en
// panne (HTTP 500 « EngineCore ») ou rend du JSON malformé dès le deuxième
// appel d'une série. Le modèle rend donc des lignes « n°|cellule|cellule »
// qu'on découpe soi-même — une barre verticale n'apparaît pas dans une cellule
// recopiée d'une facture.
const body = $input.first().json.body ?? {};
if (!/^data:image\/(?:jpeg|png|webp|gif);base64,/.test(String(body.imageBase64 || ''))) {
  return [{ json: { ok: false, error: 'imageBase64 doit être une data URL d\u2019image.' } }];
}

// Le texte OCR fait foi pour les caractères, l'image pour la mise en page.
// Mesuré : sans le texte, le modèle omet le tableau des articles.
const ocr = String(body.texte || '').slice(0, 20000);
const consigne = [
  'Voici une page de facture, en image, et le texte que la reconnaissance de',
  'caractères en a extrait. Le texte OCR fait foi pour les CARACTÈRES ;',
  "l'image fait foi pour la MISE EN PAGE (quelles cellules vont ensemble).",
  '',
  'Transcris TOUS les tableaux, sans en omettre aucun. Le tableau des articles',
  '(références, désignations, quantités, prix) doit toujours y figurer.',
  '',
  "Réponds UNIQUEMENT par des lignes de texte : pas de phrase d'introduction,",
  'pas de commentaire, pas de Markdown. Une ligne par ligne de tableau,',
  'cellules séparées par une barre verticale, précédée du numéro du tableau :',
  '1|cellule|cellule|cellule',
  '1|cellule|cellule|cellule',
  '2|cellule|cellule',
  '',
  "Les trois lignes ci-dessus ne montrent que la FORME. N'en recopie jamais le",
  'contenu : « cellule » est un emplacement, pas un mot à écrire.',
  '',
  'Tu ne calcules rien, tu ne complètes rien, tu ne corriges rien.',
  "- N'écris que des caractères présents dans le texte OCR ci-dessous.",
  '- Recopie les nombres exactement, virgule comprise : « 56,221 » reste',
  '  « 56,221 » et jamais « 56.221 ».',
  '- Cellule vide : rien entre les deux barres verticales.',
  "- Toutes les lignes d'un même tableau portent le MÊME nombre de cellules :",
  '  garde les cellules vides au lieu de les sauter, sinon les colonnes glissent.',
  "- Cellule illisible : ?  N'invente jamais un montant.",
  '- Attention aux 0 (chiffre) et O (lettre) dans les codes.',
  "- Un bloc d'adresse ou des conditions générales ne sont pas un tableau.",
  '',
  '--- TEXTE OCR ---',
  ocr,
].join('\n');

return [{ json: { ok: true, requete: {
  model: 'nvidia/nemotron-nano-12b-v2-vl',
  max_tokens: 4096,
  temperature: 0,
  top_p: 1,
  stream: false,
  messages: [{ role: 'user', content: [
    { type: 'text', text: consigne },
    { type: 'image_url', image_url: { url: body.imageBase64 } },
  ] }],
} } }];

// Découpe « n°|cellule|cellule » en tableaux. Une ligne qui ne commence pas par
// un numéro suivi d'une barre est du bavardage du modèle : on la jette plutôt
// que de la laisser polluer le classeur.
const r = $input.first().json ?? {};
if (r.error) {
  return [{ json: { ok: false, error: 'NVIDIA : ' + (r.error.message ?? JSON.stringify(r.error)) } }];
}
// Une erreur d'authentification ne revient pas en JSON : n8n emballe le corps
// texte dans « data ». Sans ce cas, une clé absente se plaignait d'une
// « réponse sans contenu texte », ce qui désigne le mauvais coupable.
if (typeof r.data === 'string') {
  return [{ json: { ok: false, error: 'NVIDIA a refusé la requête : ' + r.data.slice(0, 200) } }];
}
const texte = r.choices?.[0]?.message?.content;
if (typeof texte !== 'string') {
  return [{ json: { ok: false, error: 'Réponse du modèle sans contenu texte.' } }];
}

// Le numéro annoncé par le modèle ne signifie rien : mesuré sur cinq photos,
// il numérote tantôt les tableaux (1,1,2), tantôt chaque ligne (1 à 11),
// tantôt rien du tout (tout à 1). Le grouper dessus rendait onze « tableaux »
// d'une ligne pour une facture qui en compte trois. On ne garde le numéro que
// comme marque de début de ligne — ce filtre a jeté les 438 lignes vides d'un
// emballement du modèle — et on coupe sur le changement de nombre de colonnes.
// ponytail : deux tableaux voisins de même largeur fusionnent. Couper sur
// autre chose (une ligne d'en-tête ?) le jour où un client s'en plaint.
const tables = [];
for (const ligne of texte.split('\n')) {
  const m = ligne.trim().match(/^(\d+)\|(.*)$/);
  if (!m) continue;
  const cellules = m[2].split('|').map(s => s.trim());
  if (!cellules.some(Boolean)) continue;
  const courant = tables[tables.length - 1];
  if (courant && courant.lignes[0].length === cellules.length) courant.lignes.push(cellules);
  else tables.push({ titre: 'Tableau ' + (tables.length + 1), lignes: [cellules] });
}
if (!tables.length) {
  return [{ json: { ok: false, error: 'Aucun tableau reconnu dans la réponse du modèle.' } }];
}
return [{ json: { ok: true, tables, usage: r.usage ?? null } }];
